        public HttpResponseMessage GetAllAvailableStockSeries()
        {
            try
            {
                using (TransactionScope scope = TransactionFactory.GetTransaction())
                {
                    string token = HttpContext.Current.Request.Headers["Token"];
                    AuthenticationToken authToken = AuthenticationTokenRepository.GetSingleTokenFromCache(token);
                    int tenant = authToken.Tenant;

                    SecurityUtility.AuthenticationOnTenant(tenant);



                    FBLStockQuery stackQuery = new FBLStockQuery(tenant);

                    StockSeriesListClass result = new StockSeriesListClass() { StockSeriesList = new List<StockSeries>() };

                    IQueryable<IGrouping<int, FBLStockPM>> availableStocks = stackQuery.GetAllAvailablFBLStockPMsByTenant(tenant).GroupBy(s => s.Tenant);

                    foreach (IGrouping<int, FBLStockPM> group in availableStocks)
                    {
                        List<FBLStockPM> ordered = group.OrderBy(s => s.Number).ToList();

                        List<StockSeries> series = GetSeriesList(ordered);

                        foreach (StockSeries ser in series)
                        {
                            result.StockSeriesList.Add(ser);
                        }

                    }

                    scope.Complete();
                    return Request.CreateResponse(HttpStatusCode.OK, result);
                }
            }

            catch (Exception ex)
            {
                return Request.CreateResponse(HttpStatusCode.BadRequest, ApiExceptionBuilder.BuildException(ex));
            }
        }

