        public HttpResponseMessage GetFBLStockPMsByTenant(int tenant, int pageSize, int pageIndex)
        {
            try
            {
                string token = HttpContext.Current.Request.Headers["Token"];
                AuthenticationToken authToken = AuthenticationTokenRepository.GetSingleTokenFromCache(token);
                 

                SecurityUtility.AuthenticationOnTenant(tenant);
                //SecurityUtility.CheckContactFeature("Airline", "READ", tenant);

                FBLStockQuery mawbStackQuery = new FBLStockQuery(tenant);
                int skippedStacks = pageSize * (pageIndex - 1);

                IQueryable<FBLStockPM> myResult = mawbStackQuery.GetAllAvailablFBLStockPMsByTenant(tenant).AsQueryable().OrderBy(a => a.InsertionDate);
                myResult = myResult.Skip(skippedStacks);
                myResult = myResult.Take(pageSize);

                return Request.CreateResponse(HttpStatusCode.OK, myResult);
            }

            catch (Exception ex)
            {
                return Request.CreateResponse(HttpStatusCode.BadRequest, ApiExceptionBuilder.BuildException(ex));
            }
        }

